public final class CityHouseScreen extends Screen {
 CompoundTag data;CityHousing.House h;int tab,mode=1,page;String query="",material="minecraft:oak_planks",local="";EditBox beds,workers,period,quantity,price,supply,buy;boolean personal,production;boolean dirty;String lastOp="";
 private final CityNpcSetupScreen setupReturn; CityNpcSetupScreen setupParent(){return setupReturn;}private String focusedNpc="";
 public CityHouseScreen(CompoundTag t){this(t,null,"");} public CityHouseScreen(CompoundTag t,CityNpcSetupScreen back,String focus){super(Component.literal("房屋登记"));setupReturn=back;focusedNpc=focus;update(t);}
 public void update(CompoundTag t){var draft=h;boolean keep=dirty&&((!lastOp.equals("housesave")&&!lastOp.equals("houseview"))||t.getString("Message").startsWith("拒绝"));local="";data=t;tab=t.getInt("Tab");h=CityEconomy.JSON.fromJson(t.getString("House"),CityHousing.House.class);if(keep&&draft!=null){h.personal=draft.personal;h.purpose=draft.purpose;h.beds=draft.beds;h.workerLimit=draft.workerLimit;h.product=draft.product;h.periodSeconds=draft.periodSeconds;h.quantity=draft.quantity;h.production=draft.production;}else dirty=false;personal=h.personal;production=h.production;if(minecraft!=null)rebuildWidgets();}
 Button button(String text,int x,int y,int w,Runnable r){return addRenderableWidget(Button.builder(Component.literal(text),b->r.run()).bounds(x,y,w,20).build());}
 EditBox edit(String text,int x,int y,int w){var e=addRenderableWidget(new EditBox(font,x,y,w,18,Component.literal(text)));e.setMaxLength(64);e.setValue(text);return e;}
 void stash(){if(tab!=0||beds==null)return;try{h.beds=Integer.parseInt(beds.getValue());h.workerLimit=Integer.parseInt(workers.getValue());h.periodSeconds=Integer.parseInt(period.getValue());h.quantity=Integer.parseInt(quantity.getValue());h.personal=personal;h.production=production;dirty=true;}catch(Exception ignored){}}
 void send(String op,int x,int y,String tail,boolean flag){lastOp=op;PacketDistributor.sendToServer(new CityNetwork.Request(op,data.getString("Id"),data.getLong("HouseRevision"),x,y,tab,0,0,0,data.getString("HouseId")+(tail.isEmpty()?"":"\n"+tail),flag));}
 String personName(UUID id){if(id==null)return "未指定";for(Tag raw:data.getList("People",Tag.TAG_COMPOUND)){var t=(CompoundTag)raw;if(t.getString("Id").equals(id.toString()))return t.getString("Name");}return id.toString().substring(0,8);}
 protected void init(){String[] tabs={"产权与生产","住户名单","工人名单","建材市场"};for(int i=0;i<4;i++){int n=i;button((tab==i?"✓ ":"")+tabs[i],12+i*(width-24)/4,32,(width-30)/4,()->{stash();tab=n;mode=tab==2?2:1;page=0;rebuildWidgets();});}
  if(tab==0){button(personal?"产权：个人所有":"产权：公共所有",16,66,180,()->{stash();dirty=true;personal=!personal;h.personal=personal;rebuildWidgets();});button("所有者："+personName(h.owner),204,66,width-220,()->{stash();tab=1;mode=0;page=0;rebuildWidgets();});beds=edit(""+h.beds,130,96,74);workers=edit(""+h.workerLimit,width-100,96,80);period=edit(""+h.periodSeconds,130,124,74);quantity=edit(""+h.quantity,130,152,74);
   button("产物："+new net.minecraft.world.item.ItemStack(CityEconomy.item(h.product)).getHoverName().getString(),220,124,width-236,()->{stash();minecraft.setScreen(new CityItemPicker(this,id->{h.product=id;dirty=true;minecraft.setScreen(this);}));});button(production?"简化生产：开启":"简化生产：关闭",220,152,width-236,()->{stash();dirty=true;production=!production;h.production=production;rebuildWidgets();});button("用途："+(h.purpose.isEmpty()?data.getString("Type"):h.purpose),width-150,177,130,()->{stash();String old=h.purpose.isEmpty()?data.getString("Type"):h.purpose;h.purpose=CityRegistry.TYPES.get((CityRegistry.TYPES.indexOf(old)+1)%CityRegistry.TYPES.size());dirty=true;rebuildWidgets();});button("记录房屋血量",16,200,150,()->send("housecapture",0,0,"",false));button("保存房屋属性",174,200,150,()->{try{h.personal=personal;h.beds=Integer.parseInt(beds.getValue());h.workerLimit=Integer.parseInt(workers.getValue());h.periodSeconds=Integer.parseInt(period.getValue());h.quantity=Integer.parseInt(quantity.getValue());h.production=production;send("housesave",0,0,CityEconomy.JSON.toJson(h),false);}catch(Exception ex){local="请检查数字格式";}});
  }else if(tab==1||tab==2){var search=edit(query,16,65,width-32);search.setHint(Component.literal("搜索居民姓名或UUID"));search.setResponder(v->{focusedNpc="";query=v;page=0;rebuildWidgets();});setInitialFocus(search);var list=new ArrayList<CompoundTag>();for(Tag raw:data.getList("People",Tag.TAG_COMPOUND)){var t=(CompoundTag)raw;if((focusedNpc.isEmpty()||focusedNpc.equals(t.getString("Id")))&&(t.getString("Name")+t.getString("Id")).toLowerCase().contains(query.toLowerCase()))list.add(t);}int rows=Math.max(1,(height-150)/24),pages=Math.max(1,(list.size()+rows-1)/rows);page=Math.clamp(page,0,pages-1);for(int i=0;i<rows&&page*rows+i<list.size();i++){var t=list.get(page*rows+i);UUID id=UUID.fromString(t.getString("Id"));boolean assigned=(mode==0?Objects.equals(h.owner,id):mode==1?h.residents.contains(id):h.workers.contains(id));String title=(setupReturn!=null&&mode==1?(assigned?"已入住，点击解除 · ":"点击安排入住 · "):(assigned?"✓ ":""))+t.getString("Name")+" · "+(t.getBoolean("Dead")?"死亡":t.getString("Id").substring(0,8));button(title,16,93+i*24,width-32,()->{int oldTab=tab;if(mode==0)tab=0;send("houseperson",mode,0,id.toString(),false);tab=oldTab;});}button("上一页",16,height-58,100,()->{page=Math.max(0,page-1);rebuildWidgets();});button("下一页",124,height-58,100,()->{page=Math.min(pages-1,page+1);rebuildWidgets();});
  }else{Map<String,CityHousing.Material> market=CityEconomy.JSON.fromJson(data.getString("Market"),new TypeToken<Map<String,CityHousing.Material>>(){}.getType());var m=market.getOrDefault(material,new CityHousing.Material());button("材料："+new net.minecraft.world.item.ItemStack(CityEconomy.item(material)).getHoverName().getString(),16,64,width-32,()->minecraft.setScreen(new CityItemPicker(this,id->{material=id;minecraft.setScreen(this);})));price=edit(java.math.BigDecimal.valueOf(m.priceCents,2).toPlainString(),130,114,80);supply=edit(""+m.supply,130,142,80);buy=edit("10",130,170,80);button("保存报价/供货量",224,114,width-240,()->{try{int cents=new java.math.BigDecimal(price.getValue()).movePointRight(2).intValueExact();send("housemat",cents,Integer.parseInt(supply.getValue()),material,false);}catch(Exception ex){local="价格保留两位小数，供货量填整数";}});button(data.getBoolean("TestSupply")?"测试虚空供货：开启":"测试虚空供货：关闭",224,142,width-240,()->send("housesupply",0,0,"",!data.getBoolean("TestSupply")));button("按产权账户采购",224,170,width-240,()->{try{send("housebuy",Integer.parseInt(buy.getValue()),0,material,false);}catch(Exception ex){local="采购数量须为整数";}});}
  button("刷新",16,height-29,80,()->send("houseview",0,0,"",false));button("返回房屋名单",width-146,height-29,130,this::onClose);
 }
 public void render(GuiGraphics g,int x,int y,float f){g.fill(0,0,width,height,0xff14212c);g.drawString(font,"房屋登记 · "+data.getString("HouseName")+" · "+data.getString("Type"),16,12,0xffffdd99);if(tab==0){g.drawString(font,"可住人数",16,100,0xffffffff);g.drawString(font,"工人上限",width/2,100,0xffffffff);g.drawString(font,"间隔（模拟秒）",16,128,0xffffffff);g.drawString(font,"每人每期产量",16,156,0xffffffff);g.drawString(font,"当前血量 "+data.getInt("Health")+" / "+data.getInt("MaxHealth")+"；住户 "+h.residents.size()+"；工人 "+h.workers.size(),16,181,0xffbbddbb);g.drawString(font,font.plainSubstrByWidth(h.status,width-32),16,230,0xffddcc88);g.drawString(font,"有效产能 "+Math.round(h.quantity*data.getInt("Efficiency")/10000.0)+"份/人/期；完好率 "+Math.round(data.getInt("Efficiency")/100.0)+"%",16,251,0xffaabbcc);}else if(tab==1||tab==2)g.drawString(font,mode==0?"选择私人所有者":mode==1?"点击加入/移出住户，容量 "+h.residents.size()+" / "+h.beds:"点击加入/移出工人，容量 "+h.workers.size()+" / "+h.workerLimit,16,height-78,0xffddcc88);else{Map<String,CityHousing.Material> market=CityEconomy.JSON.fromJson(data.getString("Market"),new TypeToken<Map<String,CityHousing.Material>>(){}.getType());var m=market.get(material);g.drawString(font,"市场库存 "+(m==null?0:m.stock)+"；房屋材料库 "+h.materials.getOrDefault(material,0),16,90,0xffffdd99);g.drawString(font,"单价（银币）",16,118,0xffffffff);g.drawString(font,"每模拟分钟供货",16,146,0xffffffff);g.drawString(font,"采购数量",16,174,0xffffffff);g.drawString(font,"公共建筑由市政付款；私人建筑由所有者付款。",16,205,0xffbbccdd);g.drawString(font,"虚空供货是测试来源，真实生产职业后续补充。",16,226,0xffbbccdd);}if(tab==0||tab==3)g.drawString(font,font.plainSubstrByWidth("已保存付款方："+(data.getString("Payer").startsWith("city:")?"市政公共财富":data.getString("Payer").startsWith("person:")?"所有者 "+personName(h.owner):data.getString("Payer"))+"；余额 "+data.getLong("Balance")+" 银币",width-32),16,274,0xffbbddbb);g.drawString(font,font.plainSubstrByWidth(local.isEmpty()?data.getString("Message"):local,width-32),16,height-44,0xffffbb77);super.render(g,x,y,f);}
 public void onClose(){if(setupReturn!=null){setupReturn.resume();return;}var back=data.copy();back.putLong("Revision",data.getLong("CityRevision"));minecraft.setScreen(new CityRegisterScreen(back,0));PacketDistributor.sendToServer(new CityNetwork.Request("view",data.getString("Id"),data.getLong("CityRevision"),0,0,0,0,0,0,"",false));}
 public boolean isPauseScreen(){return false;}public void renderBackground(GuiGraphics g,int x,int y,float f){}
}
